const jobGerman={Sowing:'Aussaat',Reaping:'Ernte',Reclaiming:'Boden vorbereiten',Planting:'Pflanzen',Logging:'Holzernte',Collecting:'Sammeln',Watering:'Bewässern'};
export function translate(text,lang){return lang==='de'?(jobGerman[text]||text):(dict[text]?.[lang]||text)}
const originalText=new WeakMap(), originalAttrs=new WeakMap();
export function translatePage(root,lang){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
  while((node=walker.nextNode())){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName))continue;let original=originalText.get(node);if(original===undefined){original=node.nodeValue;originalText.set(node,original)}const stripped=original.trim();if(stripped && dict[stripped])node.nodeValue=original.replace(stripped,translate(stripped,lang));}
  root.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{let map=originalAttrs.get(el)||{};for(const key of ['placeholder','aria-label'])if(el.hasAttribute(key)){if(map[key]===undefined)map[key]=el.getAttribute(key);el.setAttribute(key,translate(map[key],lang));}originalAttrs.set(el,map)});
}
